// USD price reference config for every network. Generated by gen_subgraphs.py.
export const KIND_ETH_STABLE: i32 = 0;
export const KIND_TOKEN_ETH: i32 = 1;
export const KIND_TOKEN_STABLE: i32 = 2;

export class RefPool {
  pool: string;
  token: string;
  kind: i32;
  pricedIsToken0: boolean;
  dec0: i32;
  dec1: i32;
  discovered: boolean = false;
  constructor(pool: string, token: string, kind: i32, pricedIsToken0: boolean, dec0: i32, dec1: i32) {
    this.pool = pool;
    this.token = token;
    this.kind = kind;
    this.pricedIsToken0 = pricedIsToken0;
    this.dec0 = dec0;
    this.dec1 = dec1;
  }
}

export class V4RefPool {
  poolId: string;
  token: string;
  tokenDecimals: i32;
  discovered: boolean = false;
  constructor(poolId: string, token: string, tokenDecimals: i32) {
    this.poolId = poolId;
    this.token = token;
    this.tokenDecimals = tokenDecimals;
  }
}

